//! Runtime support for `#[mlir::op]`: typed op structs with a declarative assembly format.

use core::fmt::{self, Write};

use crate::ast::*;
use crate::parse::{Parser, R};
use crate::print::Printer;

/// A piece of custom (pretty) syntax: parses from and prints to MLIR text.
pub trait Syntax<'a>: Sized {
    fn parse(p: &mut Parser<'a, '_>) -> R<Self>;
    fn print(&self, p: &mut Printer<'_, '_>) -> fmt::Result;
}

/// A typed op generated by `#[mlir::op]`; converts to and from [`GenericOp`].
///
/// `Syntax::parse` starts right after the op name; `Syntax::print` writes the name too.
pub trait Op<'a>: Syntax<'a> + for<'g> TryFrom<&'g GenericOp<'a>> + Into<GenericOp<'a>> {
    const NAME: &'a str;
}

/// AST nodes whose custom syntax is their plain parse/print form.
macro_rules! syntax {
    ($($ty:ident => $m:ident),* $(,)?) => {$(
        impl<'a> Syntax<'a> for $ty<'a> {
            fn parse(p: &mut Parser<'a, '_>) -> R<Self> {
                p.$m()
            }
            fn print(&self, p: &mut Printer<'_, '_>) -> fmt::Result {
                write!(p, "{self}")
            }
        }
    )*};
}

syntax!(ValueRef => value_ref, Type => ty, Attribute => attr);

/// ODS spacing rules between assembly-format elements (`OpFormatGen.cpp`).
pub struct Spacer {
    space: bool,
    punct: bool,
}

impl Default for Spacer {
    fn default() -> Self {
        Self { space: true, punct: false }
    }
}

impl Spacer {
    /// `` `lit` ``; the empty literal suppresses the next space.
    pub fn lit(&mut self, p: &mut Printer<'_, '_>, s: &str) -> fmt::Result {
        let Some(&c) = s.as_bytes().first() else {
            (self.space, self.punct) = (false, true);
            return Ok(());
        };
        let before = match (s.len() != 1 && s != "->", self.punct) {
            (true, _) => true,
            (false, true) => !b">)}],".contains(&c),
            (false, false) => !b"<>(){}[],".contains(&c),
        };
        if self.space && before {
            p.write_char(' ')?;
        }
        p.write_str(s)?;
        self.space = s.len() != 1 || !b"<({[".contains(&c);
        self.punct = c != b'_' && !c.is_ascii_alphabetic();
        Ok(())
    }

    /// Before a variable / directive.
    pub fn elem(&mut self, p: &mut Printer<'_, '_>) -> fmt::Result {
        if self.space || !self.punct {
            p.write_char(' ')?;
        }
        (self.space, self.punct) = (true, false);
        Ok(())
    }

    /// After `attr-dict` (which writes its own leading space).
    pub fn dict(&mut self) {
        self.punct = false;
    }
}

impl<'a> Type<'a> {
    /// Binds a type variable to `t`, or checks it agrees with the earlier binding.
    pub fn unify(slot: &mut Option<Self>, t: Option<&Self>) -> Result<(), ()> {
        match (slot.as_ref(), t) {
            (_, None) => Err(()),
            (Some(s), Some(t)) if s != t => Err(()),
            (Some(_), Some(_)) => Ok(()),
            (None, Some(t)) => {
                *slot = Some(t.clone());
                Ok(())
            }
        }
    }
}
